namespace sv_95cc562d000440ecacf168d271806b2f.Services;

public class AppointmentService
{
    private static readonly List<string> Doctors =
    [
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Garcia"
    ];

    private static readonly List<string> AllTimeSlots =
    [
        "9:00 AM",
        "10:00 AM",
        "11:00 AM",
        "1:00 PM",
        "2:00 PM",
        "3:00 PM",
        "4:00 PM"
    ];

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all slots regardless of doctor/date
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    /// <summary>
    /// Validates server-side business rules. Returns a dictionary of
    /// field name → error message for any violations found.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject patients with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(BookAppointmentModel.Email)] = "Account has outstanding balance";
        }

        // Reject self-pay with doctors who don't accept it
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(BookAppointmentModel.Doctor)] =
                "Selected doctor does not accept self-pay patients";
        }

        // Simulate race condition on a specific time slot
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(BookAppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

public class BookAppointmentModel
{
    // Step 1
    public string PatientName { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Phone { get; set; } = string.Empty;
    public string InsuranceProvider { get; set; } = string.Empty;

    // Step 2
    public string Doctor { get; set; } = string.Empty;
    public DateTime? AppointmentDate { get; set; }
    public string TimeSlot { get; set; } = string.Empty;
    public string ReasonForVisit { get; set; } = string.Empty;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_95cc562d000440ecacf168d271806b2f.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <div class="card mb-4">
        <div class="card-header fw-semibold">Step 1 — Patient Information</div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="Model.PatientName" />
                <ValidationMessage For="() => Model.PatientName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
                @if (serverErrors.TryGetValue(nameof(Model.Email), out var emailErr))
                {
                    <div class="validation-message">@emailErr</div>
                }
            </div>
            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>

            @if (!showStep2)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                    Next
                </button>
            }
        </div>
    </div>

    @* ───── STEP 2 ───── *@
    @if (showStep2)
    {
        <div class="card mb-4">
            <div class="card-header fw-semibold">Step 2 — Appointment Details</div>
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-select" @bind-Value="Model.Doctor">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.Doctor" />
                    @if (serverErrors.TryGetValue(nameof(Model.Doctor), out var docErr))
                    {
                        <div class="validation-message">@docErr</div>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="Model.AppointmentDate"
                               @bind-Value:after="OnDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in timeSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                    @if (serverErrors.TryGetValue(nameof(Model.TimeSlot), out var slotErr))
                    {
                        <div class="validation-message">@slotErr</div>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="3" />
                    <ValidationMessage For="() => Model.ReasonForVisit" />
                </div>

                <button type="button" class="btn btn-outline-secondary me-2" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-primary me-2" @onclick="CheckAvailability"
                        disabled="@isChecking">
                    @(isChecking ? "Checking…" : "Check Availability")
                </button>
                @if (availabilityConfirmed)
                {
                    <button type="submit" class="btn btn-success">
                        Confirm Appointment
                    </button>
                }
            </div>
        </div>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully for <strong>@Model.PatientName</strong>
        with <strong>@Model.Doctor</strong> on
        <strong>@Model.AppointmentDate?.ToString("MMM dd, yyyy")</strong> at
        <strong>@Model.TimeSlot</strong>.
    </div>
}

@code {
    private BookAppointmentModel Model { get; set; } = new();
    private ValidationMessageStore? messageStore;
    private EditContext? editContext;

    private List<string> doctors = [];
    private List<string> timeSlots = [];
    private Dictionary<string, string> serverErrors = new();

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool submitted;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        messageStore = new ValidationMessageStore(editContext);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        ClearServerErrors();
        editContext!.Validate();

        // Only validate step-1 fields
        bool step1Valid =
            !string.IsNullOrWhiteSpace(Model.PatientName) &&
            !string.IsNullOrWhiteSpace(Model.Email) &&
            IsValidEmail(Model.Email) &&
            !string.IsNullOrWhiteSpace(Model.Phone) &&
            !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
        ClearServerErrors();
    }

    private async Task OnDateChanged()
    {
        availabilityConfirmed = false;
        ClearServerErrors();

        if (Model.AppointmentDate.HasValue && !string.IsNullOrWhiteSpace(Model.Doctor))
        {
            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor,
                DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        ClearServerErrors();
        availabilityConfirmed = false;

        // Client-side step-2 validation
        var step2Problems = new List<string>();
        if (string.IsNullOrWhiteSpace(Model.Doctor))
            step2Problems.Add("Doctor");
        if (!Model.AppointmentDate.HasValue || Model.AppointmentDate.Value.Date <= DateTime.Today)
            step2Problems.Add("Date");
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            step2Problems.Add("TimeSlot");
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            step2Problems.Add("Reason");
        if (Model.ReasonForVisit?.Length > 500)
            step2Problems.Add("ReasonLength");

        if (step2Problems.Count > 0)
        {
            if (step2Problems.Contains("Doctor"))
                AddServerError(nameof(Model.Doctor), "Please select a doctor.");
            if (step2Problems.Contains("Date"))
                AddServerError(nameof(Model.AppointmentDate), "Please select a future date.");
            if (step2Problems.Contains("TimeSlot"))
                AddServerError(nameof(Model.TimeSlot), "Please select a time slot.");
            if (step2Problems.Contains("Reason"))
                AddServerError(nameof(Model.ReasonForVisit), "Reason for visit is required.");
            if (step2Problems.Contains("ReasonLength"))
                AddServerError(nameof(Model.ReasonForVisit), "Reason must be 500 characters or less.");
            return;
        }

        isChecking = true;

        var errors = await AppointmentSvc.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor,
            Model.TimeSlot);

        isChecking = false;

        if (errors.Count > 0)
        {
            foreach (var (field, message) in errors)
            {
                serverErrors[field] = message;
            }
        }
        else
        {
            availabilityConfirmed = true;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed)
        {
            submitted = true;
        }
    }

    private void ClearServerErrors()
    {
        serverErrors.Clear();
    }

    private void AddServerError(string field, string message)
    {
        serverErrors[field] = message;
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

