        availabilityConfirmed = false;

        // Client-side step-2 validation
        var step2Problems = new List<string>();
        if (string.IsNullOrWhiteSpace(Model.Doctor))
            step2Problems.Add("Doctor");
        if (!Model.AppointmentDate.HasValue || Model.AppointmentDate.Value.Date <= DateTime.Today)
            step2Problems.Add("Date");
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
            step2Problems.Add("TimeSlot");
        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
            step2Problems.Add("Reason");
        if (Model.ReasonForVisit?.Length > 500)
            step2Problems.Add("ReasonLength");

        if (step2Problems.Count > 0)
        {
            if (step2Problems.Contains("Doctor"))
                AddServerError(nameof(Model.Doctor), "Please select a doctor.");
