+        if (Model.ReasonForVisit?.Length > 500)
+            step2Problems.Add("ReasonLength");
+
+        if (step2Problems.Count > 0)
+        {
+            if (step2Problems.Contains("Doctor"))
+                AddServerError(nameof(Model.Doctor), "Please select a doctor.");
+            if (step2Problems.Contains("Date"))
+                AddServerError(nameof(Model.AppointmentDate), "Please select a future date.");
+            if (step2Problems.Contains("TimeSlot"))
+                AddServerError(nameof(Model.TimeSlot), "Please select a time slot.");
+            if (step2Problems.Contains("Reason"))
+                AddServerError(nameof(Model.ReasonForVisit), "Reason for visit is required.");
+            if (step2Problems.Contains("ReasonLength"))
+                AddServerError(nameof(Model.ReasonForVisit), "Reason must be 500 characters or less.");
+            return;
+        }
+
+        isChecking = true;
+
+        var errors = await AppointmentSvc.ValidatePatientAsync(
+            Model.Email,
+            Model.InsuranceProvider,
+            Model.Doctor,
+            Model.TimeSlot);
+
+        isChecking = false;
+
+        if (errors.Count > 0)
+        {
+            foreach (var (field, message) in errors)
+            {
+                serverErrors[field] = message;
+            }
+        }
+        else
+        {
+            availabilityConfirmed = true;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityConfirmed)
+        {
+            submitted = true;
+        }
+    }
+
+    private void ClearServerErrors()
+    {
+        serverErrors.Clear();
+    }
+
+    private void AddServerError(string field, string message)
+    {
+        serverErrors[field] = message;
+    }
+
+    private static bool IsValidEmail(string email)
+    {
+        try
+        {
+            var addr = new System.Net.Mail.MailAddress(email);
+            return addr.Address == email;
+        }
+        catch
+        {
+            return false;
+        }
+    }
+}
